const S=[{"id":"S01","t":"Hallo, ich heiße Ali","te":"Hello, my name is Ali","lv":"A1","s":[["{Hallo|hallo}, {guten Tag|guten Tag}! Ich {heiße|heißen} Ali.","Hello, good day! My name is Ali."],["Das ist mein {Vorname|Vorname}. Mein {Familienname|Familienname} ist Kaya.","That is my first name. My surname is Kaya."],["Ich {komme|kommen} aus der Türkei. Das ist meine {Heimat|Heimat}.","I come from Turkey. That is my homeland."],["Jetzt {wohne|wohnen} ich in Aachen. Das ist eine {Stadt|Stadt} in Deutschland, einem {Land|Land} in Europa.","Now I live in Aachen. That is a city in Germany, a country in Europe."],["Meine {Adresse|Adresse} ist Goethestraße 5. Mein {Alter|Alter}? Ich bin 28 {Jahre|Jahr} {alt|alt}.","My address is Goethestraße 5. My age? I am 28 years old."],["Meine {Familie|Familie} ist nicht {groß|groß}: Ich {habe|haben} einen {Bruder|Bruder} und eine {Schwester|Schwester}.","My family is not big: I have a brother and a sister."],["Meine {Geschwister|Geschwister} {heißen|heißen} Can und Elif.","My siblings are called Can and Elif."],["Meine {Eltern|Eltern} {leben|leben} noch in der Türkei. Meine {Mutter|Mutter} ist {Hausfrau|Hausfrau}, mein {Vater|Vater} ist {Lehrer|Lehrer}.","My parents still live in Turkey. My mother is a housewife, my father is a teacher."],["Ich {spreche|sprechen} Türkisch und ein {bisschen|bisschen} Deutsch. Ich {lerne|lernen} {Deutsch|deutsch}.","I speak Turkish and a little German. I am learning German."],["Die {Sprache|Sprache} ist nicht {leicht|leicht}, aber sie ist {schön|schön}.","The language is not easy, but it is beautiful."],["Ich bin {Student|Student} und {studiere|studieren} in Aachen. Mein {Beruf|Beruf}? Noch keiner.","I am a student and I study in Aachen. My profession? None yet."],["Mein {Hobby|Hobby} ist {Fußball|Fußball}. Mein {Freund|Freund} Tom {spielt|spielen} auch gern.","My hobby is football. My friend Tom also likes to play."],["Hier ist meine {Nummer|Nummer}. Ich {buchstabiere|buchstabieren} meinen Namen: K-A-Y-A.","Here is my number. I spell my name: K-A-Y-A."],["{Danke|danke} und {tschüss|tschüss}! {Bis bald|bis bald} – {auf Wiedersehen|auf Wiedersehen}!","Thanks and bye! See you soon – goodbye!"]],"g":[["Verb in second place","In a German statement the conjugated verb is always the **second** idea: *Ich heiße Ali.* *Jetzt wohne ich in Aachen.* When \"Jetzt\" moves to the front, the verb stays second and the subject \"ich\" goes behind it."],["Present tense endings","ich **-e** (*ich wohne, ich komme, ich spreche*), du **-st**, er/sie **-t** (*er spielt*), wir/sie **-en** (*meine Eltern leben*). \"heißen\" is *ich heiße*, *sie heißen*."],["mein / meine","\"Mein\" goes with der- and das-nouns (*mein Vorname, mein Hobby*), \"meine\" with die-nouns and all plurals (*meine Familie, meine Eltern*)."],["haben + accusative","*Ich habe einen Bruder* (der Bruder becomes **einen** Bruder) but *eine Schwester* (die stays **eine**). Only masculine nouns change: der → den, ein → einen."]],"r":[],"tk":"","p":"","w":{"hallo":["","hallo","hello",""],"guten tag":["","guten Tag","good day, hello",""],"heißen":["","heißen","to be called",""],"vorname":["der","Vorname","first name","Vornamen"],"familienname":["der","Familienname","surname, family name","Familiennamen"],"kommen":["","kommen","to come",""],"heimat":["die","Heimat","homeland, home",""],"wohnen":["","wohnen","to live",""],"stadt":["die","Stadt","city, town","Städte"],"land":["das","Land","country; land","Länder"],"adresse":["die","Adresse","address","Adressen"],"alter":["das","Alter","age",""],"jahr":["das","Jahr","year","Jahre"],"alt":["","alt","old",""],"familie":["die","Familie","family","Familien"],"groß":["","groß","big, tall",""],"haben":["","haben","to have",""],"bruder":["der","Bruder","brother","Brüder"],"schwester":["die","Schwester","sister","Schwestern"],"geschwister":["die","Geschwister","siblings",""],"eltern":["die","Eltern","parents",""],"leben":["","leben","to live",""],"mutter":["die","Mutter","mother","Mütter"],"hausfrau":["die","Hausfrau","housewife","Hausfrauen"],"vater":["der","Vater","father","Väter"],"lehrer":["der","Lehrer","teacher","Lehrer"],"sprechen":["","sprechen","to speak",""],"bisschen":["","bisschen","a little, a bit",""],"lernen":["","lernen","to learn",""],"deutsch":["","deutsch","German",""],"sprache":["die","Sprache","language","Sprachen"],"leicht":["","leicht","easy, light",""],"schön":["","schön","beautiful, nice",""],"student":["der","Student","student (university)","Studenten"],"studieren":["","studieren","to study",""],"beruf":["der","Beruf","profession","Berufe"],"hobby":["das","Hobby","hobby","Hobbys"],"fußball":["der","Fußball","football, soccer",""],"freund":["der","Freund","friend","Freunde"],"spielen":["","spielen","to play",""],"nummer":["die","Nummer","number","Nummern"],"buchstabieren":["","buchstabieren","to spell",""],"danke":["","danke","thank you",""],"tschüss":["","tschüss","bye",""],"bis bald":["","bis bald","see you soon",""],"auf wiedersehen":["","auf Wiedersehen","goodbye",""]}},{"id":"S02","t":"Im Bürgeramt","te":"At the registration office","lv":"A1","s":[["Heute {gehe|gehen} ich zum Bürgeramt. Ich {muss|müssen} mich {anmelden|anmelden}.","Today I am going to the registration office. I have to register."],["Zuerst {nehme|nehmen} ich eine {Nummer|Nummer} aus dem {Automaten|Automat}.","First I take a number from the machine."],["Dann {warte|warten} ich. Das {dauert|dauern} {zwanzig|zwanzig} {Minuten|Minute}.","Then I wait. It takes twenty minutes."],["Endlich ruft der {Beamte|Beamte}: „Nummer 57, {bitte|bitte}!“ Ich gehe zum {Schalter|Schalter}.","At last the official calls: \"Number 57, please!\" I go to the counter."],["„Haben Sie einen {Termin|Termin}?“ – „Nein, {leider|leider} nicht.“","\"Do you have an appointment?\" – \"No, unfortunately not.\""],["„Das ist kein Problem. Hier ist das {Formular|Formular}. Bitte {füllen|ausfüllen} Sie es {aus|ausfüllen}.“","\"That is no problem. Here is the form. Please fill it in.\""],["Ich {schreibe|schreiben} meinen Namen, mein {Geburtsjahr|Geburtsjahr} und meinen {Geburtsort|Geburtsort}.","I write my name, my year of birth and my place of birth."],["Bei {Familienstand|Familienstand} steht „{ledig|ledig}“ oder „{verheiratet|verheiratet}“. Ich {kreuze|ankreuzen} „ledig“ {an|ankreuzen}.","Under marital status it says \"single\" or \"married\". I tick \"single\"."],["Der Beamte {fragt|fragen}: „Haben Sie Ihren {Ausweis|Ausweis} oder Ihren {Pass|Pass}?“ – „Hier ist mein Pass.“","The official asks: \"Do you have your ID card or your passport?\" – \"Here is my passport.\""],["„Ich bin {Ausländer|Ausländer} und {verstehe|verstehen} nicht alles. {Können|können} Sie {langsam|langsam} sprechen?“","\"I am a foreigner and do not understand everything. Can you speak slowly?\""],["„Natürlich. Wir {brauchen|brauchen} noch Ihre {Unterschrift|Unterschrift}. Bitte {unterschreiben|unterschreiben} Sie hier.“","\"Of course. We still need your signature. Please sign here.\""],["Danach {bekomme|bekommen} ich ein {Papier|Papier} mit meiner {Adresse|Adresse}. „{Vielen Dank|Vielen Dank} und {auf Wiedersehen|auf Wiedersehen}!“","Afterwards I get a paper with my address. \"Many thanks and goodbye!\""]],"g":[["Modal verb + infinitive at the end","With *müssen, können, möchten, dürfen* the second verb goes to the **end** in the infinitive: *Ich muss mich anmelden.* *Können Sie langsam sprechen?*"],["Separable verbs","*ausfüllen* splits in a main clause: *Füllen Sie das Formular **aus**.* *Ich kreuze „ledig“ **an**.* The prefix (aus, an) jumps to the end of the sentence."],["Polite request with Sie","Verb first + \"Sie\" + \"bitte\" is the polite command: *Bitte unterschreiben Sie hier.* Official people always use **Sie**, and the possessive is capitalised: *Ihren Ausweis, Ihre Unterschrift*."],["Question word order","Yes/no questions put the verb in first place: *Haben Sie einen Termin?* *Können Sie langsam sprechen?*"]],"r":[],"tk":"","p":"","w":{"gehen":["","gehen","to go",""],"müssen":["","müssen","to have to, must",""],"anmelden":["","anmelden","to register",""],"nehmen":["","nehmen","to take",""],"nummer":["die","Nummer","number","Nummern"],"automat":["der","Automat","machine, vending machine","Automaten"],"warten":["","warten","to wait",""],"dauern":["","dauern","to last, to take (time)",""],"zwanzig":["","zwanzig","twenty",""],"minute":["die","Minute","minute","Minuten"],"beamte":["der","Beamte","civil servant, official","Beamten"],"bitte":["","bitte","please",""],"schalter":["der","Schalter","counter, ticket window; switch","Schalter"],"termin":["der","Termin","appointment","Termine"],"leider":["","leider","unfortunately",""],"formular":["das","Formular","form (document)","Formulare"],"ausfüllen":["","ausfüllen","to fill in, complete, to fill a form",""],"schreiben":["","schreiben","to write",""],"geburtsjahr":["das","Geburtsjahr","year of birth","Geburtsjahre"],"geburtsort":["der","Geburtsort","place of birth","Geburtsorte"],"familienstand":["der","Familienstand","marital status",""],"ledig":["","ledig","single, unmarried",""],"verheiratet":["","verheiratet","married",""],"ankreuzen":["","ankreuzen","to tick, to mark with a cross",""],"fragen":["","fragen","to ask",""],"ausweis":["der","Ausweis","ID card","Ausweise"],"pass":["der","Pass","passport; mountain pass","Pässe"],"ausländer":["der","Ausländer","foreigner","Ausländer"],"verstehen":["","verstehen","to understand",""],"können":["","können","to be able to, can",""],"langsam":["","langsam","slowly",""],"brauchen":["","brauchen","to need",""],"unterschrift":["die","Unterschrift","signature","Unterschriften"],"unterschreiben":["","unterschreiben","to sign",""],"bekommen":["","bekommen","to get, receive",""],"papier":["das","Papier","paper","Papiere"],"adresse":["die","Adresse","address","Adressen"],"vielen dank":["","Vielen Dank","many thanks, thank you very much",""],"auf wiedersehen":["","auf Wiedersehen","goodbye",""]}},{"id":"S03","t":"Frühstück am Sonntag","te":"Sunday breakfast","lv":"A1","s":[["Es ist Sonntagmorgen und ich habe großen {Hunger|Hunger}.","It is Sunday morning and I am very hungry."],["In der {Küche|Küche} {öffne|öffnen} ich den {Kühlschrank|Kühlschrank}.","In the kitchen I open the fridge."],["Dort {finde|finden} ich {Milch|Milch}, {Butter|Butter}, {Schinken|Schinken} und {Eier|Ei}.","There I find milk, butter, ham and eggs."],["Ich {koche|kochen} zwei Eier auf dem {Herd|Herd}. Ein bisschen {Salz|Salz} dazu – das {schmeckt|schmecken} gut.","I cook two eggs on the stove. A little salt with them – that tastes good."],["Auf dem {Tisch|Tisch} {liegen|liegen} {Brot|Brot}, {Brötchen|Brötchen} und ein {Kuchen|Kuchen} von {gestern|gestern}.","On the table there are bread, rolls and a cake from yesterday."],["Ich {trinke|trinken} {Kaffee|Kaffee}, aber meine {Frau|Frau} {trinkt|trinken} {lieber|lieber} {Tee|Tee}.","I drink coffee, but my wife prefers tea."],["Die {Kinder|Kind} {möchten|möchten} {Saft|Saft} im {Glas|Glas}.","The children would like juice in a glass."],["Zum {Frühstück|Frühstück} {essen|essen} wir auch {Obst|Obst}: einen {Apfel|Apfel}, eine {Banane|Banane} und eine {Birne|Birne}.","For breakfast we also eat fruit: an apple, a banana and a pear."],["Meine {Tochter|Tochter} ist {durstig|durstig}. Sie {nimmt|nehmen} eine {Flasche|Flasche} {Wasser|Wasser}.","My daughter is thirsty. She takes a bottle of water."],["Mein {Sohn|Sohn} {frühstückt|frühstücken} nicht gern, aber heute hat er {Durst|Durst} und {Appetit|Appetit}.","My son does not like having breakfast, but today he has thirst and appetite."],["„{Guten Appetit|guten Appetit}!“, sagen alle.","\"Enjoy your meal!\" everybody says."],["Nach dem Essen {lese|lesen} ich die {Zeitung|Zeitung}.","After the meal I read the newspaper."]],"g":[["Accusative of masculine nouns","After verbs like *öffnen, haben, finden, nehmen* the object is in the accusative. Only der-nouns change: *der Kühlschrank → **den** Kühlschrank*, *ein Apfel → **einen** Apfel*. Die and das stay the same: *eine Banane, das Brot*."],["Plurals","German plurals are irregular, so learn them with the noun: *das Ei → die **Eier***, *das Kind → die **Kinder***, *die Banane → die **Bananen***. Words like *Brötchen* do not change at all."],["möchten = would like","*Die Kinder möchten Saft.* It is the polite form of \"wollen\" and goes with an object or an infinitive at the end: *Ich möchte Kaffee trinken.*"],["Vowel change verbs","Some strong verbs change their vowel for er/sie/es: *nehmen → sie **nimmt***, *lesen → er **liest***, *essen → er **isst***. Regular verbs like *trinken* just add -t: *sie trinkt*."]],"r":[],"tk":"","p":"","w":{"hunger":["der","Hunger","hunger",""],"küche":["die","Küche","kitchen","Küchen"],"öffnen":["","öffnen","to open",""],"kühlschrank":["der","Kühlschrank","refrigerator","Kühlschränke"],"finden":["","finden","to find",""],"milch":["die","Milch","milk",""],"butter":["die","Butter","butter",""],"schinken":["der","Schinken","ham",""],"ei":["das","Ei","egg","Eier"],"kochen":["","kochen","to cook",""],"herd":["der","Herd","stove, cooker","Herde"],"salz":["das","Salz","salt",""],"schmecken":["","schmecken","to taste",""],"tisch":["der","Tisch","table","Tische"],"liegen":["","liegen","to lie, be located",""],"brot":["das","Brot","bread","Brote"],"brötchen":["das","Brötchen","bread roll","Brötchen"],"kuchen":["der","Kuchen","cake","Kuchen"],"gestern":["","gestern","yesterday",""],"trinken":["","trinken","to drink",""],"kaffee":["der","Kaffee","coffee",""],"frau":["die","Frau","woman; Mrs.","Frauen"],"lieber":["","lieber","rather, preferably",""],"tee":["der","Tee","tea",""],"kind":["das","Kind","child","Kinder"],"möchten":["","möchten","would like to",""],"saft":["der","Saft","juice","Säfte"],"glas":["das","Glas","glass","Gläser"],"frühstück":["das","Frühstück","breakfast","Frühstücke"],"essen":["","essen","to eat",""],"obst":["das","Obst","fruit",""],"apfel":["der","Apfel","apple","Äpfel"],"banane":["die","Banane","banana","Bananen"],"birne":["die","Birne","pear","Birnen"],"tochter":["die","Tochter","daughter","Töchter"],"durstig":["","durstig","thirsty",""],"nehmen":["","nehmen","to take",""],"flasche":["die","Flasche","bottle","Flaschen"],"wasser":["das","Wasser","water",""],"sohn":["der","Sohn","son","Söhne"],"frühstücken":["","frühstücken","to have breakfast",""],"durst":["der","Durst","thirst",""],"appetit":["der","Appetit","appetite",""],"guten appetit":["","guten Appetit","enjoy your meal",""],"lesen":["","lesen","to read",""],"zeitung":["die","Zeitung","newspaper","Zeitungen"]}},{"id":"S04","t":"Einkaufen im Supermarkt","te":"Shopping at the supermarket","lv":"A1","s":[["Am Samstag {gehe|gehen} ich {einkaufen|einkaufen}.","On Saturday I go shopping."],["Im {Laden|Laden} an der {Ecke|Ecke} gibt es alle {Lebensmittel|Lebensmittel}.","In the shop on the corner you can get all groceries."],["{Gemüse|Gemüse} ist heute im {Angebot|Angebot}: Ein Kilo {Kartoffeln|Kartoffel} {kostet|kosten} nur 1 {Euro|Euro} 20 {Cent|Cent}.","Vegetables are on offer today: a kilo of potatoes costs only 1 euro 20 cents."],["Der {Preis|Preis} ist {günstig|günstig}. Das {Fleisch|Fleisch} ist {teuer|teuer}, aber das {Hähnchen|Hähnchen} ist {billig|billig}.","The price is good. The meat is expensive, but the chicken is cheap."],["Ich {kaufe|kaufen} auch {Reis|Reis}, {Öl|Öl}, {Tomaten|Tomate}, einen {Salat|Salat} und {Fisch|Fisch}.","I also buy rice, oil, tomatoes, a salad and fish."],["Für die Kinder nehme ich {Pommes frites|Pommes frites} und zwei {Liter|Liter} Milch.","For the children I take French fries and two litres of milk."],["Mein Mann {möchte|möchten} ein {Bier|Bier}, ich {nehme|nehmen} einen {Wein|Wein}.","My husband would like a beer, I take a wine."],["Der {Verkäufer|Verkäufer} ist freundlich. Jeder {Kunde|Kunde} bekommt eine {Tasche|Tasche}.","The shop assistant is friendly. Every customer gets a bag."],["An der {Kasse|Kasse} fragt er: „{Zahlen|zahlen} Sie {bar|bar} oder mit {Karte|Karte}?“","At the checkout he asks: \"Do you pay in cash or by card?\""],["„Ich {bezahle|bezahlen} mit Karte. Ich habe nicht viel {Geld|Geld}.“","\"I pay by card. I do not have much money.\""],["Die {Rechnung|Rechnung} ist lang. Das {Gewicht|Gewicht}? Fast vier Kilo – die Tasche ist {schwer|schwer}.","The bill is long. The weight? Almost four kilos – the bag is heavy."],["Auf dem Weg nach Hause gehe ich noch in die {Bäckerei|Bäckerei}.","On the way home I still go to the bakery."]],"g":[["Plural patterns","*die Kartoffel → die Kartoffel**n***, *die Tomate → die Tomate**n***, *das Ei → die Eier*, *der Euro → die Euro* (no change after numbers: *zwei Euro*, *zwei Liter*)."],["kosten and prices","*Das kostet 1 Euro 20.* The price is the subject: *Der Preis ist günstig.* After \"ist\" adjectives get **no ending**: *das Fleisch ist teuer*, *die Rechnung ist lang*."],["mit + dative, no article","*mit Karte*, *mit Bargeld*. Payment methods are used without an article: *Ich bezahle mit Karte.* Compare *bar zahlen* = pay in cash."],["Es gibt = there is / there are","*Im Laden gibt es alle Lebensmittel.* It always takes the accusative and the verb stays singular: *Es gibt einen Laden.*"]],"r":[],"tk":"","p":"","w":{"gehen":["","gehen","to go",""],"einkaufen":["","einkaufen","to shop, to go shopping",""],"laden":["der","Laden","shop, store","Läden"],"ecke":["die","Ecke","corner","Ecken"],"lebensmittel":["das","Lebensmittel","groceries","Lebensmittel"],"gemüse":["das","Gemüse","vegetables","Gemüse"],"angebot":["das","Angebot","offer","Angebote"],"kartoffel":["die","Kartoffel","potato","Kartoffeln"],"kosten":["","kosten","to cost",""],"euro":["der","Euro","euro","Euro"],"cent":["der","Cent","cent","Cent"],"preis":["der","Preis","price, prize","Preise"],"günstig":["","günstig","favourable, cheap",""],"fleisch":["das","Fleisch","meat",""],"teuer":["","teuer","expensive",""],"hähnchen":["das","Hähnchen","chicken","Hähnchen"],"billig":["","billig","cheap",""],"kaufen":["","kaufen","to buy",""],"reis":["der","Reis","rice",""],"öl":["das","Öl","oil","Öle"],"tomate":["die","Tomate","tomato","Tomaten"],"salat":["der","Salat","salad","Salate"],"fisch":["der","Fisch","fish","Fische"],"pommes frites":["die","Pommes frites","French fries",""],"liter":["der","Liter","liter","Liter"],"möchten":["","möchten","would like to",""],"bier":["das","Bier","beer","Biere"],"nehmen":["","nehmen","to take",""],"wein":["der","Wein","wine","Weine"],"verkäufer":["der","Verkäufer","salesperson, seller","Verkäufer"],"kunde":["der","Kunde","customer","Kunden"],"tasche":["die","Tasche","bag, pocket","Taschen"],"kasse":["die","Kasse","cash desk, checkout","Kassen"],"zahlen":["","zahlen","to pay",""],"bar":["","bar","in cash",""],"karte":["die","Karte","map, card","Karten"],"bezahlen":["","bezahlen","to pay",""],"geld":["das","Geld","money",""],"rechnung":["die","Rechnung","bill","Rechnungen"],"gewicht":["das","Gewicht","weight","Gewichte"],"schwer":["","schwer","heavy; difficult",""],"bäckerei":["die","Bäckerei","bakery","Bäckereien"]}},{"id":"S05","t":"Meine neue Wohnung","te":"My new flat","lv":"A1","s":[["Nächste {Woche|Woche} {ziehe|umziehen} ich {um|umziehen}. Ich habe eine {neu|neu}e {Wohnung|Wohnung}.","Next week I am moving. I have a new flat."],["Das {Apartment|Apartment} hat zwei {Zimmer|Zimmer} und ein kleines {Bad|Bad} mit {Dusche|Dusche}.","The apartment has two rooms and a small bathroom with a shower."],["Die Wohnung {liegt|liegen} im dritten {Stock|Stock} in einem alten {Haus|Haus}.","The flat is on the third floor in an old house."],["Das Haus hat einen {Aufzug|Aufzug}, aber ich {nehme|nehmen} lieber die {Treppe|Treppe}.","The house has a lift, but I prefer to take the stairs."],["Auf dem {Balkon|Balkon} ist {Platz|Platz} für zwei Stühle.","There is space on the balcony for two chairs."],["Die Wohnung ist {hell|hell} und {ruhig|ruhig}. Die Straße ist {leise|leise}, nicht {laut|laut}.","The flat is bright and quiet. The street is quiet, not loud."],["Der {Vermieter|Vermieter} {vermietet|vermieten} sie für 650 Euro {Miete|Miete}.","The landlord rents it out for 650 euros rent."],["Ich {miete|mieten} sie ab {Januar|Januar}.","I am renting it from January."],["Er gibt mir den {Schlüssel|Schlüssel}. Am {Eingang|Eingang} {steht|stehen} mein Name auf einem {Schild|Schild}.","He gives me the key. At the entrance my name is on a sign."],["Ich habe noch keine {Möbel|Möbel}. Ein {Bett|Bett}, einen {Schrank|Schrank} und ein {Sofa|Sofa} {kaufe|kaufen} ich im {Internet|Internet}.","I do not have any furniture yet. I buy a bed, a wardrobe and a sofa on the internet."],["Hinter dem Haus gibt es einen {Garten|Garten}. Das ist {klein|klein}, aber sehr {schön|schön}.","Behind the house there is a garden. It is small, but very beautiful."],["Im Bad ist das {Licht|Licht} {kaputt|kaputt}. Der Vermieter {repariert|reparieren} es diese Woche.","In the bathroom the light is broken. The landlord repairs it this week."],["Die {Reparatur|Reparatur} {kostet|kosten} {nichts|nichts}. Jeder {Raum|Raum} ist {fertig|fertig}.","The repair costs nothing. Every room is ready."]],"g":[["Separable verb umziehen","*Ich ziehe nächste Woche um.* In the present tense \"um\" goes to the end. In the infinitive it stays attached: *Ich muss umziehen.*"],["Adjective endings after \"ein\"","Before a noun the adjective gets an ending: *eine neue Wohnung* (die, nominative/accusative → **-e**), *ein kleines Bad* (das → **-es**), *einen alten Stuhl*. After \"ist\" there is no ending: *Die Wohnung ist neu.*"],["Prepositions of place","*im dritten Stock* (in + dem), *auf dem Balkon*, *am Eingang* (an + dem), *hinter dem Haus*. These answer \"Wo?\" (where) and take the **dative**."],["lieber = rather","*Ich nehme lieber die Treppe* = I'd rather take the stairs. \"gern → lieber → am liebsten\" is the pattern: like → prefer → like most."]],"r":[],"tk":"","p":"","w":{"woche":["die","Woche","week","Wochen"],"umziehen":["","umziehen","to move from one place to another",""],"neu":["","neu","new",""],"wohnung":["die","Wohnung","apartment, flat","Wohnungen"],"apartment":["das","Apartment","apartment","Apartments"],"zimmer":["das","Zimmer","room","Zimmer"],"bad":["das","Bad","bath, bathroom","Bäder"],"dusche":["die","Dusche","shower","Duschen"],"liegen":["","liegen","to lie, be located",""],"stock":["der","Stock","floor, storey","Stock"],"haus":["das","Haus","house","Häuser"],"aufzug":["der","Aufzug","lift","Aufzüge"],"nehmen":["","nehmen","to take",""],"treppe":["die","Treppe","stairs, staircase","Treppen"],"balkon":["der","Balkon","balcony","Balkone"],"platz":["der","Platz","seat","Plätze"],"hell":["","hell","bright, light",""],"ruhig":["","ruhig","calm",""],"leise":["","leise","quiet, soft",""],"laut":["","laut","loud",""],"vermieter":["der","Vermieter","landlord","Vermieter"],"vermieten":["","vermieten","to rent out",""],"miete":["die","Miete","rent","Mieten"],"mieten":["","mieten","to rent",""],"januar":["der","Januar","January","Januare"],"schlüssel":["der","Schlüssel","key","Schlüssel"],"eingang":["der","Eingang","entrance","Eingänge"],"stehen":["","stehen","to stand",""],"schild":["das","Schild","sign","Schilder"],"möbel":["das","Möbel","furniture","Möbel"],"bett":["das","Bett","bed","Betten"],"schrank":["der","Schrank","cupboard, wardrobe","Schränke"],"sofa":["das","Sofa","sofa","Sofas"],"kaufen":["","kaufen","to buy",""],"internet":["das","Internet","internet",""],"garten":["der","Garten","garden","Gärten"],"klein":["","klein","small, little",""],"schön":["","schön","beautiful, nice",""],"licht":["das","Licht","light","Lichter"],"kaputt":["","kaputt","broken",""],"reparieren":["","reparieren","to repair",""],"reparatur":["die","Reparatur","repair","Reparaturen"],"kosten":["","kosten","to cost",""],"nichts":["","nichts","nothing",""],"raum":["der","Raum","space, room","Räume"],"fertig":["","fertig","finished, ready",""]}},{"id":"S06","t":"Mein Tag","te":"My day","lv":"A1","s":[["Mein Tag {fängt|anfangen} früh {an|anfangen}. Um sechs {Uhr|Uhr} {stehe|aufstehen} ich {auf|aufstehen}.","My day starts early. At six o'clock I get up."],["Ich {dusche|duschen} und {wasche|waschen} mir die {Haare|Haar}.","I take a shower and wash my hair."],["Dann {ziehe|anziehen} ich meine {Kleidung|Kleidung} {an|anziehen}: eine {Jacke|Jacke} und {Schuhe|Schuh}.","Then I put on my clothes: a jacket and shoes."],["{Oft|oft} {fahre Rad|Rad fahren} ich zur {Arbeit|Arbeit}, aber heute gehe ich {zu Fuß|zu Fuß}.","I often cycle to work, but today I walk."],["Ich {arbeite|arbeiten} in einer {Firma|Firma}. Mein {Chef|Chef} ist nett und ich habe viele {Kollegen|Kollege}.","I work in a company. My boss is nice and I have many colleagues."],["Ich bin {immer|immer} {pünktlich|pünktlich}, denn ich komme nicht gern {spät|spät}.","I am always punctual, because I do not like to be late."],["Am {Vormittag|Vormittag} habe ich viel zu tun. Dann ist {Mittag|Mittag}.","In the morning I have a lot to do. Then it is noon."],["Ich mache eine {Pause|Pause} und {esse|essen} mit meinen Kollegen. Sie dauert eine {Stunde|Stunde}.","I take a break and eat with my colleagues. It lasts an hour."],["Am {Nachmittag|Nachmittag} bin ich oft {müde|müde}. Ich habe nicht viel {Zeit|Zeit}.","In the afternoon I am often tired. I do not have much time."],["Um 17 Uhr {höre|aufhören} ich {auf|aufhören}. Das ist das {Ende|Ende} vom Arbeitstag.","At 5 pm I stop. That is the end of the working day."],["Nach einer {Viertelstunde|Viertelstunde} bin ich {zu Hause|zu Hause}. Ich {koche|kochen} und esse.","After a quarter of an hour I am at home. I cook and eat."],["Am {Abend|Abend} {sehe|fernsehen} ich {fern|fernsehen}. {Später|später} {lese|lesen} ich noch ein bisschen.","In the evening I watch TV. Later I read a little."],["In der {Nacht|Nacht} {schlafe|schlafen} ich acht Stunden. Das {Wochenende|Wochenende} kommt {bald|bald}!","At night I sleep eight hours. The weekend is coming soon!"]],"g":[["Separable verbs in a row","*aufstehen* (ich stehe auf), *anfangen* (er fängt an), *anziehen* (ich ziehe an), *aufhören* (ich höre auf), *fernsehen* (ich sehe fern). Finite verb in position 2, prefix at the end."],["Time expressions","*um sechs Uhr* (at six o'clock), *am Vormittag / am Nachmittag / am Abend* (in the morning/afternoon/evening), but *in der Nacht*. Days also use **am**: *am Montag*."],["Word order with time first","Put a time expression first and the subject moves behind the verb: *Um 17 Uhr höre ich auf.* *Am Abend sehe ich fern.* *Später lese ich noch.*"],["Reflexive-like dative with body parts","*Ich wasche mir die Haare* literally \"I wash to-me the hair.\" German uses mir (dative) with body parts and clothes instead of \"my\"."]],"r":[],"tk":"","p":"","w":{"anfangen":["","anfangen","to start",""],"uhr":["die","Uhr","clock, watch; o'clock","Uhren"],"aufstehen":["","aufstehen","to get up",""],"duschen":["","duschen","to shower, to take a shower",""],"waschen":["","waschen","to wash",""],"haar":["das","Haar","hair","Haare"],"anziehen":["","anziehen","to put on (clothes), to dress",""],"kleidung":["die","Kleidung","clothing",""],"jacke":["die","Jacke","jacket","Jacken"],"schuh":["der","Schuh","shoe","Schuhe"],"oft":["","oft","often",""],"rad fahren":["","Rad fahren","to cycle",""],"arbeit":["die","Arbeit","work, job","Arbeiten"],"zu fuß":["","zu Fuß","on foot",""],"arbeiten":["","arbeiten","to work",""],"firma":["die","Firma","company, firm","Firmen"],"chef":["der","Chef","boss","Chefs"],"kollege":["der","Kollege","colleague","Kollegen"],"immer":["","immer","always",""],"pünktlich":["","pünktlich","punctual",""],"spät":["","spät","late",""],"vormittag":["der","Vormittag","morning (before noon)","Vormittage"],"mittag":["der","Mittag","noon","Mittage"],"pause":["die","Pause","break","Pausen"],"essen":["","essen","to eat",""],"stunde":["die","Stunde","hour","Stunden"],"nachmittag":["der","Nachmittag","afternoon","Nachmittage"],"müde":["","müde","tired",""],"zeit":["die","Zeit","time","Zeiten"],"aufhören":["","aufhören","to end, conclude, stop",""],"ende":["das","Ende","end","Enden"],"viertelstunde":["die","Viertelstunde","quarter of an hour","Viertelstunden"],"zu hause":["","zu Hause","at home",""],"kochen":["","kochen","to cook",""],"abend":["der","Abend","evening","Abende"],"fernsehen":["","fernsehen","to watch TV",""],"später":["","später","later",""],"lesen":["","lesen","to read",""],"nacht":["die","Nacht","night","Nächte"],"schlafen":["","schlafen","to sleep",""],"wochenende":["das","Wochenende","weekend","Wochenenden"],"bald":["","bald","soon",""]}},{"id":"S07","t":"Ich stelle mich vor","te":"I introduce myself","lv":"B1","s":[["Guten Tag, ich heiße Sara Lopez und [[ich bin 29 Jahre alt::German says \"I am 29 years old\" with sein, never haben. Ich bin 29 (Jahre alt).]].","Good day, my name is Sara Lopez and I am 29 years old."],["Ich komme [[aus Spanien::aus + dative: countries without an article take aus with no article, aus Spanien. Feminine or plural countries use an article: aus der Türkei, aus den USA.]], aber ich [[wohne seit zwei Jahren in Aachen::seit + dative describes something that started in the past and still continues. The verb stays in the PRESENT tense (wohne), not Perfekt. Jahre becomes Jahren in the dative plural.]].","I come from Spain, but I have lived in Aachen for two years."],["Ich bin [[nach Deutschland gezogen::The Perfekt of verbs of movement or change of place uses sein, not haben: ich bin gezogen, ich bin gefahren, ich bin gekommen. Cities and countries without an article take nach.]], [[weil mein Mann hier eine Stelle gefunden hat::After weil the conjugated verb (hat) goes to the END of the clause, after the participle gefunden.]].","I moved to Germany because my husband found a job here."],["Ich arbeite [[als {Ingenieurin|Ingenieur}::With professions use als and no article: ich arbeite als Ingenieurin, er arbeitet als Lehrer.]] [[bei einer {Firma|Firma}::bei + dative = working AT a company. die Firma becomes einer Firma in the dative (feminine: der / einer).]] [[in der {Innenstadt|Innenstadt}::Wo? (static location) takes in + dative: die Innenstadt, in der Innenstadt.]].","I work as an engineer at a company in the city centre."],["[[In meiner {Freizeit|Freizeit}::In + dative: die Freizeit becomes in meiner Freizeit (feminine dative: meiner).]] [[gehe ich::Inversion: when something other than the subject opens the sentence, the verb stays in second place and the subject follows: In meiner Freizeit gehe ich ...]] gern {spazieren|spazieren}.","In my free time I like to go for walks."],["Am {Wochenende|Wochenende} {koche|kochen} ich {oft|oft} mit Freunden.","At the weekend I often cook with friends."],["Ich lerne Deutsch, [[um die {Prüfung|Prüfung} zu bestehen::um ... zu + infinitive expresses a purpose when the subject stays the same (I learn, I pass). Put a comma before um, and zu stands right before the final infinitive.]].","I am learning German in order to pass the exam."],["[[Außerdem möchte ich::Außerdem (in addition) takes position 1, so the verb möchte comes right after it and the subject ich follows.]] viele neue Leute {kennenlernen|kennenlernen}.","In addition, I would like to get to know many new people."],["Ich habe [[einen Bruder und zwei Schwestern::haben needs the accusative: der Bruder becomes einen Bruder. Plural nouns (Schwestern) take no article after a number.]].","I have a brother and two sisters."],["Und du? [[Was machst du beruflich?::W-question: question word first, verb second. beruflich = in your job. With fellow candidates in the exam you say du.]] [[Woher kommst du?::Woher = where from. Wo = where, wohin = where to, woher = where from.]]","And you? What do you do for a living? Where do you come from?"],["Ich {freue|sich freuen} mich [[auf unser {Gespräch|Gespräch}::sich freuen auf + accusative = look forward to something in the future. For something already happened: sich freuen über + accusative.]].","I am looking forward to our conversation."]],"g":[["Perfekt with sein or haben","Movement or change of state → **sein** (*ich bin gezogen*), most other verbs → **haben** (*mein Mann hat gefunden*). In the exam, one correct Perfekt sentence about your past already shows B1 level."],["Verb at the end","*weil, dass, wenn, damit* send the conjugated verb to the end of the clause. *um ... zu* has no conjugated verb at all: *um die Prüfung zu bestehen*."],["Prepositions with the dative","*aus, bei, seit, mit, nach, von, zu* always take the dative. Feminine: **der / einer**, masculine and neuter: **dem / einem**, plural: **den + -n**."],["Inversion","If a time or place opens the sentence, the verb is still second: *In meiner Freizeit gehe ich ...*, *Am Wochenende koche ich ...*, *Außerdem möchte ich ...*"]],"r":[["Ich heiße ... und ich komme aus ...","Opening: name and origin."],["Ich wohne seit ... in ...","How long you have lived somewhere."],["Ich arbeite als ... bei ...","Your job or your studies (Ich studiere ... an der ...)."],["In meiner Freizeit ... ich gern ...","Hobbies, always with the verb second."],["Ich lerne Deutsch, weil ... / um ... zu ...","Give a reason; both forms are good B1."],["Und du? Was machst du beruflich?","Teil 1 also wants questions to your partner."],["Ich freue mich auf unser Gespräch.","Friendly closing."]],"tk":"Prepare **six sentences about yourself** using *seit*, *weil*, *um ... zu*, *als* and *in meiner Freizeit*. Say them aloud, then type them to Claude and write \"Ich bin fertig\" for feedback.","p":"Sprechen Teil 1","w":{"ingenieur":["der","Ingenieur","engineer","Ingenieure"],"firma":["die","Firma","company, firm","Firmen"],"innenstadt":["die","Innenstadt","city centre","Innenstädte"],"freizeit":["die","Freizeit","free time, leisure",""],"spazieren":["","spazieren","to walk (for pleasure)",""],"wochenende":["das","Wochenende","weekend","Wochenenden"],"kochen":["","kochen","to cook",""],"oft":["","oft","often",""],"prüfung":["die","Prüfung","exam, test","Prüfungen"],"kennenlernen":["","kennenlernen","to get to know",""],"sich freuen":["","sich freuen","to be happy (about), to look forward (to)",""],"gespräch":["das","Gespräch","conversation","Gespräche"]}},{"id":"S08","t":"Antwort an eine Freundin","te":"A reply to a friend's invitation","lv":"B1","s":[["Liebe Lisa,","Dear Lisa,"],["[[vielen Dank für deine {Einladung|Einladung}::danken für + accusative. Die Einladung is feminine: für + deine Einladung (nominative and accusative of die-nouns look the same).]]!","thank you very much for your invitation!"],["Ich habe mich sehr [[darüber gefreut::sich freuen über + accusative. When the reason is a whole clause, German uses da(r) + preposition: darüber, and the dass-clause follows.]], [[dass du endlich eine neue {Wohnung|Wohnung} {gefunden|finden} hast::dass-clause: the conjugated verb (hast) stands at the end, after the participle gefunden.]].","I was very happy that you have finally found a new flat."],["[[Leider kann ich nicht schon um 18 Uhr kommen::Leider is position 1, so the verb kann comes second. With a modal verb the second verb (kommen) goes to the end. schon um = already at.]], [[denn ich muss bis 19 Uhr {arbeiten|arbeiten}::denn = because, but it does NOT change the word order: verb in second place (muss). Weil would send it to the end: weil ich bis 19 Uhr arbeiten muss.]].","Unfortunately I cannot come as early as 6 pm, because I have to work until 7 pm."],["[[Deshalb komme ich erst gegen 20 Uhr::Deshalb = therefore, takes position 1 and the verb follows immediately: Deshalb komme ich. gegen + accusative = around a time. erst = not before.]]. Ist das in Ordnung?","Therefore I will only come at around 8 pm. Is that all right?"],["Natürlich {bringe|mitbringen} ich etwas [[mit::mitbringen is separable: ich bringe etwas mit. The prefix mit stands at the very end of a main clause.]]. [[Soll ich einen {Salat|Salat} oder lieber einen {Kuchen|Kuchen} mitbringen?::sollen is used to ask what someone wants you to do. oder lieber = or rather. Both words are masculine accusative: einen.]]","Of course I will bring something. Shall I bring a salad or rather a cake?"],["Und [[wie komme ich am besten zu dir?::zu + dative for going to a person: zu dir, zu meiner Freundin. am besten = superlative of gut, the best way.]] Ich {kenne|kennen} die {Straße|Straße} nicht.","And what is the best way to get to you? I do not know the street."],["[[Kannst du mir bitte die {Adresse|Adresse} {schicken|schicken}?::schicken takes a dative person and an accusative thing: mir (to me) + die Adresse. A pronoun comes before a noun.]]","Can you please send me the address?"],["Ich freue mich schon sehr [[auf den {Abend|Abend}::sich freuen auf + accusative. der Abend becomes auf den Abend.]]!","I am already looking forward to the evening!"],["Liebe Grüße, Mia","Best wishes, Mia"]],"g":[["Connectors and word order","**denn** (main clause, verb 2nd), **weil** (verb at the end), **deshalb** (verb right after it), **dass** (verb at the end). One sentence per connector is a good B1 target in Schreiben."],["The four Leitpunkte","This email answers four typical points: *thanks / time and reason / what to bring / the way*. Always cover every point in its own sentence or two, and do not leave one out, because a missing point is marked down heavily."],["Separable verbs and modals","*mitbringen* → *Ich bringe etwas mit.* With a modal: *Soll ich etwas mitbringen?* (the verb stays in one piece at the end)."],["Dative and accusative together","*Kannst du mir die Adresse schicken?* mir = dative (who gets it), die Adresse = accusative (what). In Sprachbausteine, test each gap with the question wem? / was?"]],"r":[["Vielen Dank für deine E-Mail / Einladung.","Always start with thanks, informal Liebe/Lieber + name."],["Ich habe mich sehr darüber gefreut, dass ...","Show your reaction to a piece of news."],["Leider kann ich nicht ..., denn / weil ...","Decline or limit politely and give a reason."],["Soll ich etwas mitbringen?","Offer help, a typical Leitpunkt."],["Wie komme ich am besten zu dir?","Ask for the way."],["Kannst du mir bitte ... schicken?","Request something."],["Ich freue mich auf ... / Bis bald! / Liebe Grüße","Friendly closing."]],"tk":"Write your own reply (80–100 words) to a friend's party invitation: **thank her, say when you can come and why you are late, ask what to bring, ask for the way**. Use *denn*, *weil* and *deshalb* once each. Send it to Claude and write \"Ich bin fertig\".","p":"Schreiben informell · Sprachbausteine Teil 1","w":{"einladung":["die","Einladung","invitation","Einladungen"],"wohnung":["die","Wohnung","apartment, flat","Wohnungen"],"finden":["","finden","to find",""],"arbeiten":["","arbeiten","to work",""],"mitbringen":["","mitbringen","to bring along",""],"salat":["der","Salat","salad","Salate"],"kuchen":["der","Kuchen","cake","Kuchen"],"kennen":["","kennen","to know",""],"straße":["die","Straße","street","Straßen"],"adresse":["die","Adresse","address","Adressen"],"schicken":["","schicken","to send",""],"abend":["der","Abend","evening","Abende"]}},{"id":"S09","t":"Eine Beschwerde schreiben","te":"Writing a complaint","lv":"B1","s":[["Sehr geehrte Damen und Herren,","Dear Sir or Madam,"],["ich schreibe Ihnen, [[weil die Heizung in meiner Wohnung seit einer Woche kaputt ist::weil sends the verb (ist) to the end. seit + dative: eine Woche becomes seit einer Woche. The present tense ist is used because the problem still exists.]].","I am writing to you because the heating in my flat has been broken for a week."],["[[Obwohl ich Sie schon zweimal angerufen habe::obwohl = although, a contrast. The verb habe is at the end. Because this clause opens the sentence, the main clause starts with its verb.]], [[ist bisher niemand gekommen::After a subordinate clause in position 1 the main clause begins with the verb: ist niemand gekommen. Kommen uses sein in the Perfekt.]].","Although I have already called you twice, nobody has come so far."],["Als {Mieter|Mieter} habe ich [[ein {Recht|Recht} auf eine funktionierende Heizung::Recht auf + accusative. Adjective after eine (feminine accusative) gets -e: eine funktionierende Heizung.]].","As a tenant I have a right to a working heating system."],["Dies ist schon meine zweite {Beschwerde|Beschwerde}, [[deshalb kann ich nachts kaum schlafen::deshalb is position 1, the verb kann follows. kaum = hardly. kann + infinitive schlafen at the end.]].","This is already my second complaint, so I can hardly sleep at night."],["[[Ich möchte Sie bitten, die Heizung so schnell wie möglich zu reparieren::bitten + infinitive clause with zu, separated by a comma: ... zu reparieren. so schnell wie möglich = as quickly as possible (so + adjective + wie).]].","I would like to ask you to repair the heating as quickly as possible."],["[[Könnten Sie mir bis nächsten Freitag einen {Termin|Termin} nennen?::Könnten is Konjunktiv II of können: the most polite request. bis + time needs no article here: bis nächsten Freitag. mir (dative) + einen Termin (accusative).]]","Could you give me an appointment by next Friday?"],["[[Falls das nicht möglich ist::falls = if, in case. Same word order as wenn: the verb ist is at the end.]], [[werde ich einen {Anwalt|Anwalt} informieren::The main clause after a falls-clause starts with the verb: werde ich ... informieren. werden + infinitive = future.]].","If that is not possible, I will inform a lawyer."],["[[Ich bedanke mich im Voraus für Ihre Bemühungen::sich bedanken für + accusative. im Voraus = in advance. Ihre is capitalised in formal letters.]].","I thank you in advance for your efforts."],["Mit freundlichen Grüßen","Yours faithfully"]],"g":[["Formal vs informal","Formal: *Sehr geehrte Damen und Herren*, *Sie / Ihre* (capital letters), *Mit freundlichen Grüßen*. Informal: *Liebe Lisa*, *du / deine*, *Liebe Grüße*."],["Connector choice in Sprachbausteine Teil 2","**weil** (reason, verb end), **obwohl** (contrast, verb end), **deshalb** (result, verb next), **falls / wenn** (condition, verb end), **damit** (purpose, verb end). Read the gap sentence and ask: reason, contrast, result or purpose?"],["Konjunktiv II for politeness","*Könnten Sie ...?*, *Würden Sie ...?*, *Ich würde mich freuen* sound much more polite than *Können Sie ...?*. Learn these three fixed forms for formal letters."],["Verb after a subordinate clause","When a dependent clause comes first, the main clause starts with its verb: *Obwohl ich angerufen habe, **ist** niemand gekommen.* This is the most common B1 mistake, so check it every time."]],"r":[["Ich schreibe Ihnen, weil ...","Formal reason for writing."],["Leider muss ich mich über ... beschweren.","Official complaint."],["Ich möchte Sie bitten, ... zu ...","Polite demand."],["Könnten Sie mir bitte ... mitteilen?","Polite question in a formal letter."],["Bitte ... Sie das bis spätestens ...","Set a deadline (Frist)."],["Falls ..., werde ich ...","Mention a consequence."],["Ich bedanke mich im Voraus.","Formal thanks before you close."]],"tk":"A. **Sprachbausteine:** cover the connectors in the letter and decide for each gap: *weil, obwohl, deshalb, falls*. B. **Schreiben:** write your own complaint about a broken washing machine (4 points: the problem, the consequence for you, your request, a deadline). Send it to Claude with \"Ich bin fertig\".","p":"Schreiben formell · Sprachbausteine Teil 2","w":{"mieter":["der","Mieter","tenant","Mieter"],"recht":["das","Recht","right; law","Rechte"],"beschwerde":["die","Beschwerde","complaint","Beschwerden"],"termin":["der","Termin","appointment","Termine"],"anwalt":["der","Anwalt","lawyer, advocate","Anwälte"]}},{"id":"S10","t":"Mein Thema: Homeoffice","te":"My topic: working from home","lv":"B1","s":[["[[Ich möchte euch etwas über das Thema Homeoffice erzählen::erzählen takes a dative person (euch) and an accusative thing (etwas). über + accusative: über das Thema. In the exam you say du or ihr to your partner.]].","I would like to tell you something about the topic of working from home."],["[[Zuerst möchte ich erklären, warum das Thema wichtig ist::warum starts an indirect question, so the verb ist goes to the end. Zuerst is position 1, so möchte comes second.]].","First I would like to explain why the topic is important."],["In meiner {Firma|Firma} [[arbeiten viele {Kollegen|Kollege} zwei Tage zu Hause::Inversion: after In meiner Firma the verb (arbeiten) comes before the subject (viele Kollegen). zu Hause = at home (no movement), nach Hause = going home.]].","In my company many colleagues work two days at home."],["[[Meiner Meinung nach hat Homeoffice mehr {Vorteile|Vorteil} als {Nachteile|Nachteil}::Meiner Meinung nach (dative after nach) counts as position 1, so hat comes next. mehr ... als = more ... than.]].","In my opinion working from home has more advantages than disadvantages."],["[[Ein großer Vorteil ist, dass man keine {Zeit|Zeit} im {Stau|Stau} verliert::After ist comes a dass-clause: verb at the end. man = one, people in general. keine + noun negates it (kein is for nouns, nicht for verbs).]].","A big advantage is that you do not lose time in a traffic jam."],["[[Außerdem kann man den Tag selbst planen::kann + infinitive at the end. der Tag is masculine, so accusative = den Tag.]] und hat mehr Zeit für die Familie.","You can also plan your day yourself and have more time for the family."],["[[Andererseits gibt es auch Nachteile::Einerseits ... andererseits = on the one hand ... on the other. Es gibt + accusative (Nachteile, plural).]].","On the other hand there are also disadvantages."],["Zum Beispiel sieht man seine Kollegen nur auf dem {Bildschirm|Bildschirm}. [[Wenn man zu Hause arbeitet, fehlt oft der Kontakt::The wenn-clause opens the sentence, so its verb (arbeitet) is at the end, and the main clause starts with its verb: fehlt oft der Kontakt.]].","For example you only see your colleagues on the screen. When you work at home, contact is often missing."],["[[Ich finde, dass ein Mix aus beiden ideal ist::Ich finde / glaube / denke, dass ... gives your opinion; the verb ist stands at the end. aus + dative: aus beiden.]].","I think that a mix of both is ideal."],["[[Ich persönlich würde drei Tage im Büro arbeiten::würde + infinitive = Konjunktiv II for what you would do or prefer. The infinitive arbeiten is at the end. im = in dem.]] und zwei zu Hause.","Personally I would work three days in the office and two at home."],["[[Was denkt ihr darüber?::denken über + accusative, so darüber = about it. Use it to give the turn to your partner.]] Wie ist das bei euch?","What do you think about it? What is it like for you?"]],"g":[["Structure of a Teil 2 talk","**1** Say your topic. **2** Give your opinion (*Meiner Meinung nach ...*). **3** Name advantages and disadvantages (*Ein Vorteil ist ..., andererseits ...*). **4** Give a personal example. **5** Ask your partner a question."],["dass-clauses for opinions","*Ich finde, dass ...*, *Ich glaube, dass ...*, *Ein Vorteil ist, dass ...* The verb always goes to the end. Do not forget the comma before dass."],["Comparing","*mehr ... als* (more than), *weniger ... als*, *so ... wie* (as ... as), *besser, schneller, billiger*. Simple comparisons make your opinion sound clear."],["Conditions","*Wenn man zu Hause arbeitet, fehlt der Kontakt.* The main clause after wenn starts with its verb. If you mix this up, say two short sentences instead."]],"r":[["Mein Thema ist ... / Ich möchte über ... sprechen.","Opening line."],["Meiner Meinung nach ...","Opinion."],["Ein Vorteil ist, dass ... / Ein Nachteil ist, dass ...","Pro and con."],["Einerseits ..., andererseits ...","Show both sides."],["Zum Beispiel ... / Bei mir ist das so: ...","Personal example."],["Ich persönlich würde ...","Your own choice."],["Was denkst du darüber? / Wie ist das bei dir?","Give the turn to your partner."]],"tk":"Pick another topic: *Auto oder Fahrrad?* or *Online einkaufen*. Prepare **one opinion sentence, two advantages, two disadvantages, one personal example and one question** for your partner. Speak for about 1.5 minutes, then type it to Claude and write \"Ich bin fertig\".","p":"Sprechen Teil 2","w":{"firma":["die","Firma","company, firm","Firmen"],"kollege":["der","Kollege","colleague","Kollegen"],"vorteil":["der","Vorteil","advantage","Vorteile"],"nachteil":["der","Nachteil","disadvantage","Nachteile"],"zeit":["die","Zeit","time","Zeiten"],"stau":["der","Stau","traffic jam","Staus"],"bildschirm":["der","Bildschirm","screen","Bildschirme"]}},{"id":"S11","t":"Gemeinsam einen Ausflug planen","te":"Planning a trip together","lv":"B1","s":[["Anna: Wir wollen am Samstag einen {Ausflug|Ausflug} machen. [[Wie wäre es mit einer {Wanderung|Wanderung}?::Wie wäre es mit + dative = what about ...? die Wanderung becomes mit einer Wanderung (feminine dative). A soft way to make a suggestion.]]","Anna: We want to go on a trip on Saturday. How about a hike?"],["Tom: Das ist eine gute Idee, aber [[es soll regnen::sollen can report a forecast or hearsay: es soll regnen = it is supposed to rain.]]. [[Wir könnten stattdessen ins Museum gehen::Wir könnten = Konjunktiv II for a polite suggestion. ins = in das: direction (wohin?) takes in + accusative. gehen at the end.]].","Tom: That is a good idea, but it is supposed to rain. We could go to the museum instead."],["Anna: Hmm, ich möchte lieber draußen sein. [[Was hältst du davon, wenn wir an den {See|See} fahren?::halten von + dative, so davon = about it. Wenn-clause: the verb fahren is at the end. an den See: wohin? = an + accusative, der See becomes den See.]]","Anna: Hmm, I would rather be outside. What do you think about us driving to the lake?"],["Tom: Gern, aber [[nur, wenn das {Wetter|Wetter} gut ist::nur wenn = only if; the verb ist goes to the end.]]. [[Ich schlage vor, dass wir früh losfahren::vorschlagen is separable (ich schlage ... vor). In a dass-clause the verb stays whole: dass wir früh losfahren. losfahren = set off.]].","Tom: Gladly, but only if the weather is good. I suggest that we set off early."],["Anna: Einverstanden. [[Wann sollen wir uns {treffen|treffen}?::sich treffen is reflexive: wir → uns. sollen is used to arrange things: Wann sollen wir ...? Wo sollen wir ...?]] Um neun Uhr am {Bahnhof|Bahnhof}?","Anna: Agreed. When shall we meet? At nine o'clock at the station?"],["Tom: [[Neun Uhr ist mir ein bisschen zu früh::zu + adjective = too. mir = dative of the person it affects: too early for me.]]. Wie wäre es mit zehn?","Tom: Nine o'clock is a little too early for me. How about ten?"],["Anna: Das passt mir auch. [[Wer kauft die {Fahrkarten|Fahrkarte}?::Wer = who, followed by the verb. kaufen takes the accusative: die Fahrkarten (plural, no article needed after a number).]]","Anna: That suits me as well. Who buys the tickets?"],["Tom: [[Ich kann mich darum kümmern::sich kümmern um + accusative, so darum = about it. kann + infinitive at the end. mich because ich = reflexive pronoun.]]. Und du {bringst|mitbringen} das Essen [[mit::mitbringen is separable, the prefix mit goes to the end.]]?","Tom: I can take care of that. And you bring the food?"],["Anna: Ja, [[ich nehme belegte Brötchen und {Obst|Obst} mit::mitnehmen is separable: ich nehme ... mit. Brötchen is a plural noun.]].","Anna: Yes, I will take sandwiches and fruit."],["Tom: Super. Dann machen wir das so. Bis Samstag!","Tom: Great. Then let us do it like that. See you on Saturday!"]],"g":[["What Teil 3 wants","You and your partner plan something together. Decide **Wann? Wo? Wer macht was? Was brauchen wir?** and reach an agreement. Both candidates must speak about equally."],["Suggest, agree, refuse","Suggest: *Wie wäre es mit ...? / Wir könnten ... / Ich schlage vor, dass ...* Agree: *Einverstanden. / Das passt mir.* Refuse politely: *Das ist mir zu ..., aber wie wäre es mit ...?*"],["sollen and können in questions","*Wann sollen wir uns treffen?* asks for a decision. *Wir könnten ...* offers an idea. Both have the infinitive at the end."],["Wohin and wo","Direction (**wohin?**) = accusative: *ins Museum, an den See*. Location (**wo?**) = dative: *im Museum, am See*. This is a frequent Sprachbausteine question."]],"r":[["Wie wäre es mit ...? / Was hältst du davon, wenn ...?","Make a suggestion."],["Wir könnten ...","Polite idea."],["Ich schlage vor, dass ...","Formal suggestion."],["Einverstanden. / Das passt mir. / Gute Idee!","Agree."],["Ich habe einen anderen Vorschlag.","Disagree politely."],["Wann / Wo sollen wir uns treffen?","Fix time and place."],["Wer kümmert sich um ...? / Ich kann mich darum kümmern.","Share the tasks."],["Dann machen wir das so.","Close the discussion."]],"tk":"Plan with Claude as your partner: a **Geburtstagsfeier** for a colleague. Decide *when, where, who brings what* and who invites the others. Prepare eight phrases from the list above and then type your part of the dialogue to Claude. Write \"Ich bin fertig\" for feedback.","p":"Sprechen Teil 3","w":{"ausflug":["der","Ausflug","excursion","Ausflüge"],"wanderung":["die","Wanderung","hike","Wanderungen"],"see":["der","See","lake","Seen"],"wetter":["das","Wetter","weather",""],"treffen":["","treffen","to meet",""],"bahnhof":["der","Bahnhof","railway station","Bahnhöfe"],"fahrkarte":["die","Fahrkarte","ticket","Fahrkarten"],"mitbringen":["","mitbringen","to bring along",""],"obst":["das","Obst","fruit",""]}}];const TOT=4478,COV=282;